// ===== DATA: append future content here; engine reads every pack dynamically =====
window.TRACK_PACKS=[
 {packId:'sector01',packName:'STARTER PACK — SECTOR 01',unlockRequirement:[],tracks:[
  {id:'cyber-grid',number:'01',name:'Cyber Grid',biome:'grid',description:'Synth-asphalt beneath the retro neon skyline.',laps:3,steps:[{id:'race',label:'Finish 1st in the 3-Lap Circuit Race',type:'race',rule:'first'},{id:'boss',label:'Defeat Boss Byte in 1v1 Showdown',type:'boss',boss:'Byte',reward:{paint:'Neon Grid Iridescent Paint'}}]},
  {id:'neon-monsoon',number:'02',name:'Neon Monsoon',biome:'rain',description:'Rain-slick expressway, reflective puddles and city glow.',laps:3,steps:[{id:'race',label:'Finish Top 2 + earn 1,000 Drift Score in one race',type:'race',rule:'top2drift'},{id:'boss',label:'Defeat Boss Kuro in 1v1 Showdown',type:'boss',boss:'Kuro',reward:{paint:'Aqua Wet-Look Clearcoat',glow:'Cyan Underglow'}}]},
  {id:'sub-zero',number:'03',name:'Sub-Zero Abyss',biome:'ice',description:'A glacial cavern with fractured ice and treacherous apexes.',laps:3,steps:[{id:'race',label:'Finish 1st with fewer than 3 wall resets',type:'race',rule:'firstclean'},{id:'boss',label:'Defeat Glacier — Sector Finale Showdown',type:'boss',boss:'Glacier',reward:{paint:'Frosted Matte Ice Paint',kit:'Heavy Bash Bar Kit',badge:'Sector 01 Master Badge'}}]}
 ]},
 {packId:'volcanic',packName:'DLC PACK 02 — VOLCANIC & SKY CIRCUITS',unlockRequirement:[{id:'sector01.sub-zero.boss',label:'Complete Sector 01 Finale (Defeat Boss Glacier)'}],tracks:Array.from({length:10},(_,i)=>({id:'volcanic-'+(i+4),number:String(i+4).padStart(2,'0'),name:i===0?'Cinder Run':'Sky Circuit '+(i+4),biome:i%2?'rain':'grid',description:'Coming soon · volcanic high-altitude circuit.',laps:3,steps:[]}))},
 {packId:'horizon',packName:'DLC PACK 03 — HORIZON & FOSSIL ROTUNDA',unlockRequirement:[{id:'sector01.sub-zero.boss',label:'Complete Sector 01 Finale (Defeat Boss Glacier)'}],tracks:Array.from({length:13},(_,i)=>({id:'horizon-'+(i+14),number:String(i+14),name:i===0?'Fossil Rotunda':'Horizon '+(i+14),biome:i%2?'ice':'grid',description:'Coming soon · ancient ruins meet the outer rim.',laps:3,steps:[]}))}
];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const SAVE_KEY='neonRushCareer_v1';
const defaults={completed:{},credits:0,unlocks:{paints:['Gloss Clearcoat','Matte Stealth','Carbon Weave','Metallic Flake','Chameleon'],kits:['Stock','GT Carbon Wing','Ducktail','Twin-Aero Split Wing'],glows:['Cyan','Magenta','Amber']},loadout:{paint:'Gloss Clearcoat',kit:'Stock',glow:'#39edff',flame:'#ff38a8',rim:82},settings:{mode:'classic',sensitivity:1,invert:false,scale:100},hud:{},stats:{wins:0,drift:0,badge:false}};
function loadSave(){try{return Object.assign(structuredClone(defaults),JSON.parse(localStorage.getItem(SAVE_KEY)||'{}'))}catch(e){return structuredClone(defaults)}}
let save=loadSave();function persist(){localStorage.setItem(SAVE_KEY,JSON.stringify(save));}
function stepKey(pack,track,step){return `${pack}.${track}.${step}`}
function isDone(id){return !!save.completed[id]}
function completeStep(id,reward=0){if(!isDone(id)){save.completed[id]=true;save.credits+=reward;persist();return true}return false}
function packUnlocked(pack){return !pack.unlockRequirement?.length||pack.unlockRequirement.every(x=>isDone(x.id))}
function trackUnlocked(pack,index){if(!packUnlocked(pack))return false;if(index===0)return true;const prev=pack.tracks[index-1];return prev.steps?.every(s=>isDone(stepKey(pack.packId,prev.id,s.id)))??true}
function allCompleted(){return Object.values(save.completed).filter(Boolean).length}
function rewardParts(reward){if(!reward)return;['paint','kit','glow','badge'].forEach(k=>{if(reward[k]){const group=k==='paint'?'paints':k==='kit'?'kits':k==='glow'?'glows':null;if(group&&!save.unlocks[group].includes(reward[k]))save.unlocks[group].push(reward[k]);if(k==='badge')save.stats.badge=true}})}
function renderCareer(){const host=$('#packList');host.innerHTML='';window.TRACK_PACKS.forEach(pack=>{const open=packUnlocked(pack),card=document.createElement('article');card.className='pack-card'+(open?'':' locked');card.innerHTML=`<div class="card-top"><div><div class="panel-kicker">${pack.packId.toUpperCase()}</div><h3>${pack.packName}</h3></div><span class="badge">${open?'AVAILABLE':'LOCKED'}</span></div>`;
 if(!open){const ul=document.createElement('ul');ul.className='steps';pack.unlockRequirement.forEach(s=>{const li=document.createElement('li');li.className=isDone(s.id)?'done':'';li.textContent=s.label;ul.appendChild(li)});card.appendChild(ul)}
 const grid=document.createElement('div');grid.className='track-grid';pack.tracks.forEach((track,i)=>{const unlocked=trackUnlocked(pack,i),tc=document.createElement('div');tc.className='track-card'+(unlocked?'':' locked');tc.innerHTML=`<div class="card-top"><h4>${track.number} / ${track.name}</h4><span class="badge">${unlocked?'OPEN':'LOCKED'}</span></div><p>${track.description}</p>`;
 if(track.steps?.length){const ul=document.createElement('ul');ul.className='steps';track.steps.forEach(s=>{const li=document.createElement('li');li.className=isDone(stepKey(pack.packId,track.id,s.id))?'done':'';li.textContent=s.label;ul.appendChild(li)});tc.appendChild(ul)}else if(pack.packId!=='sector01'){const li=document.createElement('ul');li.className='steps';(pack.unlockRequirement||[]).forEach(s=>{const it=document.createElement('li');it.className=isDone(s.id)?'done':'';it.textContent=s.label;li.appendChild(it)});tc.appendChild(li)}
 const b=document.createElement('button');b.className='btn'+(unlocked?' primary':'');b.disabled=!unlocked||pack.packId!=='sector01';b.textContent=pack.packId!=='sector01'?'COMING SOON':unlocked?(track.steps.every(s=>isDone(stepKey(pack.packId,track.id,s.id)))?'REPLAY TRACK':'RACE NOW'):'LOCKED';b.onclick=()=>startRace(pack,track);tc.appendChild(b);grid.appendChild(tc)});card.appendChild(grid);host.appendChild(card)});}
function renderHome(){const first=window.TRACK_PACKS[0].tracks.find(t=>!t.steps.every(s=>isDone(stepKey(window.TRACK_PACKS[0].packId,t.id,s.id))))||window.TRACK_PACKS[0].tracks[0];$('#homeChallenge').textContent=first.name.toUpperCase();$('#homeDesc').textContent=first.description;$('#creditsHome').textContent=String(save.credits).padStart(4,'0');$('#masteryHome').textContent=`${allCompleted()}/6`}
function showScreen(id){$$('.screen').forEach(x=>x.classList.toggle('active',x.id===id));$('#raceHud').style.display='none';}
function showCareer(){renderCareer();showScreen('career')}

