function showCareer(){renderCareer();showScreen('career')}
// ===== PROCEDURAL WEBGL WORLD =====
const scene=new THREE.Scene();scene.background=new THREE.Color(0x050a14);scene.fog=new THREE.FogExp2(0x07121d,.0065);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,500);
const renderer=new THREE.WebGLRenderer({canvas:$('#game'),antialias:false,powerPreference:'high-performance',alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;
scene.add(new THREE.HemisphereLight(0x9bdfff,0x151023,1.25));const sun=new THREE.DirectionalLight(0xd8f7ff,2.1);sun.position.set(-20,35,-15);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const world={objects:[],track:null,player:null,bots:[],particles:[],skids:[],biome:'grid',paused:false,mode:'menu'};
function own(o){scene.add(o);world.objects.push(o);return o}
function matDispose(m){(Array.isArray(m)?m:[m]).forEach(x=>{if(x){for(const k of ['map','normalMap','bumpMap','roughnessMap','metalnessMap','emissiveMap'])if(x[k])x[k].dispose();x.dispose()}})}
function clearWorld(){world.objects.forEach(o=>{scene.remove(o);o.traverse?.(n=>{if(n.geometry)n.geometry.dispose();if(n.material)matDispose(n.material)})});world.objects=[];world.particles=[];world.skids=[];world.player=null;world.bots=[];}
const texCache={};function surfaceTextures(biome){if(texCache[biome])return texCache[biome];const c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d');x.fillStyle=biome==='ice'?'#789caf':biome==='rain'?'#252f40':'#292e3b';x.fillRect(0,0,512,512);for(let i=0;i<6200;i++){const a=Math.random(),s=Math.random()*2+0.2;x.globalAlpha=.04+Math.random()*.16;x.fillStyle=biome==='ice'?(Math.random()>.5?'#e7ffff':'#214e76'):(Math.random()>.5?'#d9faff':'#03060a');x.fillRect(Math.random()*512,Math.random()*512,s*2,s)}x.globalAlpha=1;
 if(biome==='grid'){x.strokeStyle='#38eaff';x.globalAlpha=.12;x.lineWidth=1;for(let i=0;i<=512;i+=32){x.beginPath();x.moveTo(i,0);x.lineTo(i,512);x.stroke();x.beginPath();x.moveTo(0,i);x.lineTo(512,i);x.stroke()}}
 if(biome==='rain'){for(let i=0;i<55;i++){x.fillStyle='#75e6fa';x.globalAlpha=.12;x.beginPath();x.ellipse(Math.random()*512,Math.random()*512,12+Math.random()*32,3+Math.random()*8,Math.random(),0,Math.PI*2);x.fill()}}
 if(biome==='ice'){x.strokeStyle='#d5ffff';x.globalAlpha=.22;for(let i=0;i<26;i++){x.beginPath();x.moveTo(Math.random()*512,Math.random()*512);x.lineTo(Math.random()*512,Math.random()*512);x.lineTo(Math.random()*512,Math.random()*512);x.stroke()}}
 const map=new THREE.CanvasTexture(c);map.wrapS=map.wrapT=THREE.RepeatWrapping;map.repeat.set(3,3);map.anisotropy=4;const n=document.createElement('canvas');n.width=n.height=256;const nx=n.getContext('2d');nx.fillStyle='#8080ff';nx.fillRect(0,0,256,256);for(let i=0;i<2000;i++){nx.fillStyle=`rgb(${110+Math.random()*50},${110+Math.random()*50},255)`;nx.fillRect(Math.random()*256,Math.random()*256,2,2)}const normal=new THREE.CanvasTexture(n);const r=document.createElement('canvas');r.width=r.height=128;const rx=r.getContext('2d');rx.fillStyle=biome==='rain'?'#666':'#b8b8b8';rx.fillRect(0,0,128,128);for(let i=0;i<400;i++){rx.globalAlpha=Math.random()*.6;rx.fillStyle='#fff';rx.fillRect(Math.random()*128,Math.random()*128,3,3)}const rough=new THREE.CanvasTexture(r);texCache[biome]={map,normal,rough};return texCache[biome]}
const rx=27,rz=16.5,roadW=10;function pointAt(t,scale=1){return new THREE.Vector3(rx*scale*Math.cos(t),0,rz*scale*Math.sin(t))}function headingAt(t){return Math.atan2(rx*Math.sin(t),-rz*Math.cos(t))}
function createLoopMesh(scaleOuter,scaleInner,y,material){const verts=[],uv=[],idx=[],N=192;for(let i=0;i<=N;i++){const t=i/N*Math.PI*2;const a=pointAt(t,scaleOuter),b=pointAt(t,scaleInner);verts.push(a.x,y,a.z,b.x,y,b.z);uv.push(i/N*12,0,i/N*12,1);if(i<N){const k=i*2;idx.push(k,k+1,k+2,k+1,k+3,k+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return own(new THREE.Mesh(g,material))}
function makeTrack(biome){world.biome=biome;const t=surfaceTextures(biome);const ground=new THREE.Mesh(new THREE.PlaneGeometry(180,130),new THREE.MeshStandardMaterial({color:biome==='ice'?0x0c2437:0x07111c,roughness:.96}));ground.rotation.x=-Math.PI/2;ground.position.y=-.7;own(ground);
 const roadMat=new THREE.MeshStandardMaterial({map:t.map,normalMap:t.normal,normalScale:new THREE.Vector2(.27,.27),roughnessMap:t.rough,roughness:biome==='rain'?.25:biome==='ice'?.36:.75,metalness:biome==='rain'?.35:.18,side:THREE.DoubleSide});createLoopMesh((rx+roadW/2)/rx,(rx-roadW/2)/rx,.05,roadMat);
 const roadMesh=world.objects.at(-1); // ellipse depth is adjusted below by vertex positions
 const pos=roadMesh.geometry.attributes.position;for(let i=0;i<pos.count;i++)pos.setZ(i,pos.getZ(i)*(rz/rx));pos.needsUpdate=true;roadMesh.geometry.computeVertexNormals();
 const edgeColor=biome==='ice'?0x68dfff:biome==='rain'?0x29daff:0x43f5ff;for(const scale of [(rx+roadW/2)/rx,(rx-roadW/2)/rx]){const pts=[];for(let i=0;i<=192;i++){const p=pointAt(i/192*Math.PI*2,scale);pts.push(new THREE.Vector3(p.x,.16,p.z))}const line=new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:edgeColor}));own(line)}
 // alternating curb blocks and the center racing dash
 for(let i=0;i<64;i++){const a=i/64*Math.PI*2,p=pointAt(a),q=pointAt(a,(rx+roadW*.48)/rx);q.z*=rz/rx;const curb=new THREE.Mesh(new THREE.BoxGeometry(1.05,.14,.42),new THREE.MeshStandardMaterial({color:i%2?0x162333:0xff327e,emissive:i%2?0x062b36:0x4a0825,emissiveIntensity:1.2}));curb.position.set(q.x,.18,q.z);curb.rotation.y=headingAt(a);own(curb)}
 // towers around the circuit
 for(let i=0;i<30;i++){const a=i/30*Math.PI*2,p=pointAt(a,1.75);p.z*=rz/rx;const h=4+Math.random()*13,w=1.3+Math.random()*2.5;const tower=new THREE.Mesh(new THREE.BoxGeometry(w,h,w),new THREE.MeshStandardMaterial({color:biome==='ice'?0x16344d:0x111d32,metalness:.68,roughness:.32,emissive:biome==='ice'?0x07344d:0x071a36,emissiveIntensity:1.1}));tower.position.set(p.x,h/2-.3,p.z);own(tower);const stripe=new THREE.Mesh(new THREE.BoxGeometry(w+.06,.14,w+.06),new THREE.MeshBasicMaterial({color:i%2?0x35eaff:0xff38aa}));stripe.position.set(p.x,h*.68,p.z);own(stripe)}
 world.track={biome,rx,rz,roadW};}

